export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // مسار الذكاء الاصطناعي
    if (url.pathname === "/api/chat" && request.method === "POST") {
      return handleChat(request, env);
    }
    if (url.pathname === "/api/chat" && request.method === "OPTIONS") {
      return new Response(null, { status: 204 });
    }

    // أي مسار تاني (الصفحة الرئيسية) بيرجع صفحة الموقع نفسها
    return new Response(decodeHtml(), {
      headers: { "Content-Type": "text/html; charset=UTF-8" },
    });
  },
};

function decodeHtml() {
  const binary = atob(HTML_B64);
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
}

async function handleChat(request, env) {
  const keys = [];
  if (env.GROQ_API_KEYS) {
    keys.push(...env.GROQ_API_KEYS.split(",").map((k) => k.trim()).filter(Boolean));
  }
  for (let i = 1; i <= 5; i++) {
    const v = env[`GROQ_API_KEY_${i}`];
    if (v && v.trim()) keys.push(v.trim());
  }
  const uniqueKeys = [...new Set(keys)];

  if (!uniqueKeys.length) {
    return json({ error: { message: "لا يوجد مفتاح Groq مُعدّ على السيرفر" } }, 500);
  }

  let body;
  try {
    body = await request.json();
  } catch (e) {
    return json({ error: { message: "Invalid JSON body" } }, 400);
  }

  const RATE_LIMIT_RETRY_DELAYS = [300, 600, 1200, 2000];
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  let lastStatus = 500;
  let lastData = { error: { message: "فشل غير معروف" } };

  for (let round = 0; round < 2; round++) {
    for (let i = 0; i < uniqueKeys.length; i++) {
      const key = uniqueKeys[i];
      let response, data;
      try {
        response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${key}`,
          },
          body: JSON.stringify(body),
        });
        data = await response.json();
      } catch (err) {
        lastStatus = 502;
        lastData = { error: { message: "تعذر الوصول لخدمة Groq: " + err.message } };
        continue;
      }

      const isRateLimited =
        response.status === 429 ||
        data?.error?.type === "rate_limit_exceeded" ||
        data?.error?.code === "rate_limit_exceeded";

      if (!isRateLimited) {
        return json(data, response.status);
      }

      lastStatus = response.status;
      lastData = data;
    }
    if (round === 0) await sleep(RATE_LIMIT_RETRY_DELAYS[round]);
  }

  return json(lastData, lastStatus || 429);
}

function json(obj, status) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

const HTML_B64 = "";
